import React, { useState } from "react";

const TicTacToe = () => {
  const [board, setBoard] = useState(Array(9).fill(null)); // Game board
  const [isXNext, setIsXNext] = useState(true); // To alternate turns

  const calculateWinner = (squares) => {
    const lines = [
      [0, 1, 2],
      [3, 4, 5],
      [6, 7, 8],
      [0, 3, 6],
      [1, 4, 7],
      [2, 5, 8],
      [0, 4, 8],
      [2, 4, 6],
    ];
    for (let line of lines) {
      const [a, b, c] = line;
      if (squares[a] && squares[a] === squares[b] && squares[a] === squares[c]) {
        return squares[a];
      }
    }
    return null;
  };

  const handleClick = (index) => {
    if (board[index] || calculateWinner(board)) return; // Ignore if already clicked or game is over
    const newBoard = [...board];
    newBoard[index] = isXNext ? "X" : "O";
    setBoard(newBoard);
    setIsXNext(!isXNext);
  };

  const handleReset = () => {
    setBoard(Array(9).fill(null));
    setIsXNext(true);
  };

  const winner = calculateWinner(board);
  const status = winner
    ? `Winner: ${winner}`
    : board.includes(null)
    ? `Next Player: ${isXNext ? "X" : "O"}`
    : "Draw!";

  return (
    <div style={{ textAlign: "center", fontFamily: "Arial, sans-serif" }}>
      <h1>Tic-Tac-Toe</h1>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 100px)", gap: "10px", margin: "20px auto", width: "fit-content" }}>
        {board.map((value, index) => (
          <button
            key={index}
            onClick={() => handleClick(index)}
            style={{
              width: "100px",
              height: "100px",
              fontSize: "2rem",
              fontWeight: "bold",
              background: "#f0f0f0",
              border: "2px solid #333",
              cursor: "pointer",
            }}
          >
            {value}
          </button>
        ))}
      </div>
      <h2>{status}</h2>
      <button onClick={handleReset} style={{ padding: "10px 20px", fontSize: "1rem", cursor: "pointer" }}>
        Reset Game
      </button>
    </div>
  );
};

export default TicTacToe;
